// ============================================================================
// CFO Virtuel - Calcul financier (delai de paiement, prevision de tresorerie
// 13 semaines, detection d'anomalies). Toute la logique de calcul vit ICI :
// Gemini (noeud suivant) ne fait qu'interpreter et rediger, jamais recalculer.
// ============================================================================

const SEUIL_ALERTE_TRESORERIE = 15000;   // parametrable : seuil d'alerte tresorerie (EUR)
const FORECAST_WEEKS = 13;               // horizon de prevision (semaines)
const SEUIL_DEGRADATION_JOURS = 10;      // ecart (jours) entre les 2 fenetres de 3 mois pour flaguer une degradation
const Z_SCORE_SEUIL = 2;                 // seuil d'ecart-type pour une depense anormale
const FENETRE_ANOMALIE_DEPENSE_JOURS = 30; // parametrable : n'afficher que les depenses anormales des N derniers jours
const CATEGORIES_ANOMALIE_DEPENSES = ['Frais generaux', 'Loyer', 'Salaires', 'Emprunt', 'Abonnements'];
// NB : "Encaissement client" et "Paiement fournisseur" sont volontairement exclus
// de la detection d'anomalies par categorie : leurs montants varient naturellement
// avec la taille des commandes/clients, ce qui generait un bruit statistique sans
// valeur pour le dirigeant. Les paiements fournisseurs exceptionnels sont deja
// couverts par la prevision de tresorerie (tension detectee sur le solde).

function normalizeText(s) {
  let t = String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  t = t.replace(/\b(d|l)'/g, '');
  t = t.replace(/\b(de|du|des|le|la|les)\b/g, ' ');
  return t.replace(/[^a-z0-9]+/g, '');
}

function toNumber(v) {
  if (typeof v === 'number') return v;
  if (v === null || v === undefined || v === '') return 0;
  let s = String(v).trim().replace(/\s/g, '').replace(/€/g, '');
  if (/^-?\d+,\d+$/.test(s)) s = s.replace(',', '.');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
}

function fmtEur(n) {
  return n.toLocaleString('fr-FR', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 });
}

function toDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    if (v > 20000 && v < 90000) {
      return DateTime.fromMillis(Date.UTC(1899, 11, 30) + v * 86400000);
    }
  }
  const s = String(v).trim();
  if (!s) return null;
  let dt = DateTime.fromISO(s);
  if (dt.isValid) return dt;
  dt = DateTime.fromFormat(s, 'dd/MM/yyyy');
  if (dt.isValid) return dt;
  dt = DateTime.fromFormat(s, 'M/d/yyyy');
  if (dt.isValid) return dt;
  const native = new Date(s);
  if (!isNaN(native.getTime())) return DateTime.fromJSDate(native);
  return null;
}

function getVal(row, field) {
  if (row[field] !== undefined) return row[field];
  const target = normalizeText(field);
  for (const key of Object.keys(row)) {
    if (normalizeText(key) === target) return row[key];
  }
  return undefined;
}

const txRows = $('Transactions bancaires').all().map((i) => i.json);
const facClientsRows = $('Factures clients').all().map((i) => i.json);
const facFournisseursRows = $('Factures fournisseurs').all().map((i) => i.json);
const chargesRows = $('Charges récurrentes').all().map((i) => i.json);
const soldeRows = $('Solde bancaire de départ').all().map((i) => i.json);

const now = DateTime.now().startOf('day');

const transactions = txRows
  .map((r) => ({ date: toDate(getVal(r, 'date')), libelle: getVal(r, 'libelle'), montant: toNumber(getVal(r, 'montant')), categorie: getVal(r, 'categorie') }))
  .filter((t) => t.date);
if (!transactions.length) {
  const premiere = txRows[0] ? JSON.stringify(txRows[0]) : 'aucune ligne recue';
  throw new Error(`Aucune transaction bancaire lue (onglet "Transactions bancaires") - lignes recues: ${txRows.length}, premiere ligne: ${premiere}. Verifier les en-tetes de colonnes (date, libelle, montant, categorie) et le format des dates.`);
}

const soldeDepartRow = soldeRows[0];
if (!soldeDepartRow) throw new Error('Onglet "Solde bancaire de depart" vide ou introuvable.');
const soldeDepart = toNumber(getVal(soldeDepartRow, 'solde'));
const soldeActuel = soldeDepart + transactions.reduce((s, t) => s + t.montant, 0);

function parseFactures(rows, cleTiers) {
  return rows
    .map((r) => ({
      numero: getVal(r, 'numero'),
      [cleTiers]: getVal(r, cleTiers),
      montant: toNumber(getVal(r, 'montant')),
      date_emission: toDate(getVal(r, 'date_emission')),
      date_echeance: toDate(getVal(r, 'date_echeance')),
      date_paiement: getVal(r, 'date_paiement') ? toDate(getVal(r, 'date_paiement')) : null,
    }))
    .filter((f) => f.date_emission && f.date_echeance);
}

const facturesClients = parseFactures(facClientsRows, 'client');
if (!facturesClients.length) {
  const premiere = facClientsRows[0] ? JSON.stringify(facClientsRows[0]) : 'aucune ligne recue';
  throw new Error(`Aucune facture client lue (onglet "Factures clients") - lignes recues: ${facClientsRows.length}, premiere ligne: ${premiere}. Verifier les en-tetes de colonnes et le format des dates.`);
}
const facturesFournisseurs = parseFactures(facFournisseursRows, 'fournisseur');
if (!facturesFournisseurs.length) {
  const premiere = facFournisseursRows[0] ? JSON.stringify(facFournisseursRows[0]) : 'aucune ligne recue';
  throw new Error(`Aucune facture fournisseur lue (onglet "Factures fournisseurs") - lignes recues: ${facFournisseursRows.length}, premiere ligne: ${premiere}. Verifier les en-tetes de colonnes et le format des dates.`);
}

const chargesRecurrentes = chargesRows
  .map((r) => ({
    libelle: getVal(r, 'libelle'),
    categorie: getVal(r, 'categorie'),
    montant: toNumber(getVal(r, 'montant')),
    frequence: getVal(r, 'frequence'),
    prochaine_echeance: toDate(getVal(r, 'prochaine_echeance')),
    intervalle_jours: toNumber(getVal(r, 'intervalle_jours')),
  }))
  .filter((c) => c.prochaine_echeance);
if (!chargesRecurrentes.length) {
  const premiere = chargesRows[0] ? JSON.stringify(chargesRows[0]) : 'aucune ligne recue';
  throw new Error(`Aucune charge recurrente lue (onglet "Charges recurrentes") - lignes recues: ${chargesRows.length}, premiere ligne: ${premiere}. Verifier les en-tetes de colonnes et le format des dates.`);
}

// --- Delai de paiement (une seule metrique, coherente, globale et par client) ---
// Definition : nombre de jours entre l'echeance et le paiement reel (ou, pour une
// facture encore ouverte et deja en retard, entre l'echeance et aujourd'hui).
// Ce n'est PAS le DSO comptable classique (encours / CA x nb jours), qui melange
// volume de vente et vitesse de paiement et se lit mal dans un briefing oral -
// on ne garde qu'un seul indicateur, directement actionnable : "vos clients
// paient en moyenne X jours apres l'echeance".

function delaiFacture(f, referenceNow) {
  if (f.date_paiement) {
    return { delai: Math.round(f.date_paiement.diff(f.date_echeance, 'days').days), statut: 'payee' };
  }
  if (f.date_echeance < referenceNow) {
    return { delai: Math.round(referenceNow.diff(f.date_echeance, 'days').days), statut: 'ouverte_en_retard' };
  }
  return null;
}

const troisMois = now.minus({ months: 3 });
const sixMois = now.minus({ months: 6 });
const moyenne = (arr) => (arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null);

const clients = [...new Set(facturesClients.map((f) => f.client))];
const parClient = clients
  .map((client) => {
    const facturesDuClient = facturesClients.filter((f) => f.client === client);
    const recentes = facturesDuClient.filter((f) => f.date_emission >= troisMois);
    const precedentes = facturesDuClient.filter((f) => f.date_emission >= sixMois && f.date_emission < troisMois);

    const delaisRecents = recentes.map((f) => delaiFacture(f, now)).filter(Boolean).map((d) => d.delai);
    const delaisPrecedents = precedentes.map((f) => delaiFacture(f, now)).filter(Boolean).map((d) => d.delai);

    const delaiMoyenRecent = moyenne(delaisRecents);
    const delaiMoyenPrecedent = moyenne(delaisPrecedents);

    const encoursOuvert = facturesDuClient.filter((f) => !f.date_paiement).reduce((s, f) => s + f.montant, 0);
    const facturesOuvertesEnRetard = facturesDuClient.filter((f) => !f.date_paiement && f.date_echeance < now);
    const retardMax = facturesOuvertesEnRetard.length
      ? Math.max(...facturesOuvertesEnRetard.map((f) => Math.round(now.diff(f.date_echeance, 'days').days)))
      : 0;

    let degradation = false;
    let variation = null;
    if (delaiMoyenRecent !== null && delaiMoyenPrecedent !== null) {
      variation = Math.round(delaiMoyenRecent - delaiMoyenPrecedent);
      degradation = variation >= SEUIL_DEGRADATION_JOURS;
    }

    return {
      client,
      delai_moyen_3_derniers_mois_jours: delaiMoyenRecent !== null ? Math.round(delaiMoyenRecent) : null,
      delai_moyen_3_mois_precedents_jours: delaiMoyenPrecedent !== null ? Math.round(delaiMoyenPrecedent) : null,
      variation_jours: variation,
      degradation_detectee: degradation,
      encours_ouvert_eur: Math.round(encoursOuvert * 100) / 100,
      encours_ouvert_fmt: fmtEur(Math.round(encoursOuvert * 100) / 100),
      retard_max_jours_facture_ouverte: retardMax,
    };
  })
  .sort((a, b) => (b.variation_jours ?? -999) - (a.variation_jours ?? -999));

const facturesOuvertes = facturesClients.filter((f) => !f.date_paiement);
const encoursClientsTotal = facturesOuvertes.reduce((s, f) => s + f.montant, 0);

const tousDelaisRecents = facturesClients
  .filter((f) => f.date_emission >= troisMois)
  .map((f) => delaiFacture(f, now))
  .filter(Boolean)
  .map((d) => d.delai);
const delaiMoyenPaiementJours = tousDelaisRecents.length
  ? Math.round(tousDelaisRecents.reduce((a, b) => a + b, 0) / tousDelaisRecents.length)
  : null;

// --- Prevision de tresorerie sur 13 semaines ---

const delaiAjustementParClient = {};
parClient.forEach((c) => {
  delaiAjustementParClient[c.client] = c.delai_moyen_3_derniers_mois_jours ?? c.delai_moyen_3_mois_precedents_jours ?? 0;
});

function genererOccurrencesCharge(charge, debut, fin) {
  const occ = [];
  let d = charge.prochaine_echeance;
  while (d <= fin) {
    if (d >= debut) occ.push({ date: d, montant: charge.montant, libelle: charge.libelle });
    d = d.plus({ days: charge.intervalle_jours });
  }
  return occ;
}

const finHorizon = now.plus({ weeks: FORECAST_WEEKS });

const encaissementsAttendus = facturesClients
  .filter((f) => !f.date_paiement)
  .map((f) => {
    const delai = delaiAjustementParClient[f.client] || 0;
    const dateEncaissementPrevue = f.date_echeance.plus({ days: Math.max(0, Math.round(delai)) });
    return { date: dateEncaissementPrevue, montant: f.montant, source: `Facture ${f.numero} - ${f.client}` };
  })
  .filter((e) => e.date >= now && e.date <= finHorizon);

const decaissementsFournisseurs = facturesFournisseurs
  .filter((f) => !f.date_paiement)
  .map((f) => ({ date: f.date_echeance, montant: f.montant, source: `Facture ${f.numero} - ${f.fournisseur}` }))
  .filter((d) => d.date >= now && d.date <= finHorizon);

let decaissementsCharges = [];
chargesRecurrentes.forEach((c) => {
  decaissementsCharges = decaissementsCharges.concat(genererOccurrencesCharge(c, now, finHorizon));
});

const semaines = [];
let soldeCourant = soldeActuel;
let debutSemaine = now;
let horizonFiableSemaines = 0;
for (let s = 1; s <= FORECAST_WEEKS; s++) {
  const finSemaine = debutSemaine.plus({ days: 7 });
  const encaissementsSemaine = encaissementsAttendus
    .filter((e) => e.date >= debutSemaine && e.date < finSemaine)
    .reduce((sum, e) => sum + e.montant, 0);
  const decaissementsFournisseursSemaine = decaissementsFournisseurs
    .filter((d) => d.date >= debutSemaine && d.date < finSemaine)
    .reduce((sum, d) => sum + d.montant, 0);
  const decaissementsChargesSemaine = decaissementsCharges
    .filter((d) => d.date >= debutSemaine && d.date < finSemaine)
    .reduce((sum, d) => sum + d.montant, 0);
  const decaissementsSemaine = decaissementsFournisseursSemaine + decaissementsChargesSemaine;
  const fluxNet = encaissementsSemaine - decaissementsSemaine;
  soldeCourant = Math.round((soldeCourant + fluxNet) * 100) / 100;
  if (encaissementsSemaine !== 0 || decaissementsFournisseursSemaine !== 0) horizonFiableSemaines = s;
  semaines.push({
    semaine: s,
    debut: debutSemaine.toISODate(),
    fin: finSemaine.minus({ days: 1 }).toISODate(),
    encaissements_eur: Math.round(encaissementsSemaine * 100) / 100,
    encaissements_fmt: fmtEur(Math.round(encaissementsSemaine * 100) / 100),
    decaissements_eur: Math.round(decaissementsSemaine * 100) / 100,
    decaissements_fmt: fmtEur(Math.round(decaissementsSemaine * 100) / 100),
    flux_net_eur: Math.round(fluxNet * 100) / 100,
    flux_net_fmt: fmtEur(Math.round(fluxNet * 100) / 100),
    solde_fin_semaine_eur: soldeCourant,
    solde_fin_semaine_fmt: fmtEur(soldeCourant),
    sous_seuil: soldeCourant < SEUIL_ALERTE_TRESORERIE,
  });
  debutSemaine = finSemaine;
}
const semainesSousSeuil = semaines.filter((s) => s.sous_seuil);
const semainesSousSeuilFiables = semainesSousSeuil.filter((s) => s.semaine <= horizonFiableSemaines);

// --- Depenses anormales (z-score "leave-one-out" par categorie) ---
// Le regroupement par categorie se fait sur une cle normalisee (accents/casse
// ignores) pour que "Frais generaux" et "Frais généraux" alimentent la MEME
// population statistique, quelle que soit l'orthographe retenue dans le Sheet.

const CATEGORIES_ANOMALIE_NORMALISEES = CATEGORIES_ANOMALIE_DEPENSES.map(normalizeText);
const parCategorie = {};
transactions.forEach((t) => {
  const norm = normalizeText(t.categorie);
  if (!CATEGORIES_ANOMALIE_NORMALISEES.includes(norm)) return;
  if (!parCategorie[norm]) parCategorie[norm] = { label: t.categorie, txs: [] };
  parCategorie[norm].txs.push(t);
});

function moyenneEcartType(valeurs) {
  const n = valeurs.length;
  if (n < 2) return { moyenne: valeurs[0] ?? 0, ecartType: 0 };
  const m = valeurs.reduce((a, b) => a + b, 0) / n;
  const variance = valeurs.reduce((a, b) => a + (b - m) ** 2, 0) / (n - 1);
  return { moyenne: m, ecartType: Math.sqrt(variance) };
}

const anomaliesDepenses = [];
Object.values(parCategorie).forEach(({ label, txs }) => {
  if (txs.length < 5) return; // pas assez de donnees pour une base statistique fiable
  txs.forEach((t, idx) => {
    const autres = txs.filter((_, i) => i !== idx).map((x) => x.montant);
    const { moyenne: m, ecartType } = moyenneEcartType(autres);
    if (ecartType === 0) return;
    const z = (t.montant - m) / ecartType;
    if (Math.abs(z) > Z_SCORE_SEUIL) {
      anomaliesDepenses.push({
        date: t.date.toISODate(),
        libelle: t.libelle,
        montant_eur: t.montant,
        montant_fmt: fmtEur(t.montant),
        categorie: label,
        moyenne_categorie_eur: Math.round(m * 100) / 100,
        moyenne_categorie_fmt: fmtEur(Math.round(m * 100) / 100),
        ecart_type_categorie_eur: Math.round(ecartType * 100) / 100,
        z_score: Math.round(z * 100) / 100,
      });
    }
  });
});
anomaliesDepenses.sort((a, b) => Math.abs(b.z_score) - Math.abs(a.z_score));
const anomaliesRecentes = anomaliesDepenses.filter((a) => DateTime.fromISO(a.date) >= now.minus({ days: FENETRE_ANOMALIE_DEPENSE_JOURS }));

// --- Detail chiffre (message Telegram separe, genere ici - pas par Gemini) ---

function escTelegram(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/([_*`\[])/g, '\\$1');
}

let detail = `Détail chiffré - Atlas Distribution\n`;
detail += `Généré le ${now.toFormat('dd/MM/yyyy')}\n\n`;
detail += `TRÉSORERIE\nSolde actuel : ${fmtEur(soldeActuel)}\n`;
detail += `Horizon fiable de la prévision : ${horizonFiableSemaines} semaine(s) (au-delà, plus aucune facture connue, projection indicative uniquement)\n`;
if (semainesSousSeuilFiables.length) {
  detail += `ALERTE - Semaines sous le seuil de ${fmtEur(SEUIL_ALERTE_TRESORERIE)} (horizon fiable) :\n`;
  semainesSousSeuilFiables.forEach((s) => {
    detail += `  - S${s.semaine} (${s.debut} au ${s.fin}) : ${fmtEur(s.solde_fin_semaine_eur)}\n`;
  });
} else {
  detail += `Aucune semaine sous le seuil de ${fmtEur(SEUIL_ALERTE_TRESORERIE)} sur l'horizon fiable.\n`;
}
if (semainesSousSeuil.length > semainesSousSeuilFiables.length) {
  detail += `(Au-delà de l'horizon fiable, ${semainesSousSeuil.length - semainesSousSeuilFiables.length} semaine(s) supplémentaire(s) apparaissent sous le seuil faute de nouvelles factures connues - à ne pas lire comme une alerte confirmée.)\n`;
}
detail += `\nDÉLAI DE PAIEMENT\nRetard moyen (tous clients, 3 derniers mois) : ${delaiMoyenPaiementJours ?? 'N/A'} jour(s) après échéance\n`;
detail += `Encours clients total (factures non payées) : ${fmtEur(encoursClientsTotal)}\n`;
const clientsDegrades = parClient.filter((c) => c.degradation_detectee);
if (clientsDegrades.length) {
  detail += `Clients en dégradation :\n`;
  clientsDegrades.forEach((c) => {
    detail += `  - ${c.client} : +${c.variation_jours}j (récent : ${c.delai_moyen_3_derniers_mois_jours}j vs précédent : ${c.delai_moyen_3_mois_precedents_jours}j)\n`;
  });
} else {
  detail += `Aucun client en dégradation notable.\n`;
}
detail += `\nDÉPENSES ANORMALES (${FENETRE_ANOMALIE_DEPENSE_JOURS} derniers jours)\n`;
if (anomaliesRecentes.length) {
  anomaliesRecentes.forEach((a) => {
    detail += `  - ${a.date} - ${a.libelle} : ${a.montant_fmt} (moyenne catégorie : ${a.moyenne_categorie_fmt}, z=${a.z_score})\n`;
  });
} else {
  detail += `Aucune détectée sur cette période.\n`;
}

return [{
  json: {
    meta: {
      entreprise: 'Atlas Distribution',
      date_generation: now.toISO(),
      seuil_alerte_tresorerie_eur: SEUIL_ALERTE_TRESORERIE,
      fenetre_anomalie_depense_jours: FENETRE_ANOMALIE_DEPENSE_JOURS,
    },
    tresorerie: {
      solde_actuel_eur: Math.round(soldeActuel * 100) / 100,
      solde_actuel_fmt: fmtEur(Math.round(soldeActuel * 100) / 100),
      horizon_fiable_semaines: horizonFiableSemaines,
      semaines,
      semaines_sous_seuil_horizon_fiable: semainesSousSeuilFiables,
      semaines_sous_seuil_indicatif: semainesSousSeuil.filter((s) => s.semaine > horizonFiableSemaines),
    },
    delai_paiement: {
      delai_moyen_paiement_jours: delaiMoyenPaiementJours,
      encours_clients_total_eur: Math.round(encoursClientsTotal * 100) / 100,
      encours_clients_total_fmt: fmtEur(Math.round(encoursClientsTotal * 100) / 100),
      par_client: parClient,
    },
    anomalies_depenses: anomaliesRecentes,
    detail_telegram_markdown: escTelegram(detail),
  },
}];
